// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    FakeToken token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new FakeToken();
    }

    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }

    function testFuzz_property(uint256 premium, uint256 fee, address taker, address recipient) public {
        vm.assume(taker != address(0) && taker != address(token) && taker != address(c));
        vm.assume(recipient != address(0));
        fee = bound(fee, 1, 29);
        premium = bound(premium, 1000, 1e24);
        vm.warp(1000);

        c.setFee(fee);
        token.mint(address(this), premium);
        token.approve(address(c), premium);

        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);
        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(this),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: premium,
            duration: 1 days,
            expiration: block.timestamp + 1 hours,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        vm.prank(taker);
        c.fillOrder(order, hex"ff", new uint256[](0));

        require(c.unclaimedFees(address(token)) > 0, "setup: no fees accrued");

        c.withdrawFees(address(token), recipient);

        assertTrue(c.unclaimedFees(address(token)) == 0, "fees must be zeroed after withdrawal");
    }
}

contract FakeToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
